       const canvas=document.createElement('canvas');
       canvas.width=W;canvas.height=H;
       const ctx=canvas.getContext('2d');
       ctx.fillStyle='#151816';ctx.fillRect(0,0,W,H);

       // Header
       ctx.textAlign='center';ctx.textBaseline='alphabetic';
       ctx.fillStyle='#edf2ee';ctx.font='700 54px system-ui, sans-serif';
       ctx.fillText(pairLabel,W/2,85);
       ctx.fillStyle='#63c2c8';ctx.font='500 36px system-ui, sans-serif';
       ctx.fillText(filterLabel,W/2,145);
       ctx.fillStyle='#aeb8b1';ctx.font='400 28px system-ui, sans-serif';
       ctx.fillText('See what we have in common',W/2,192);

       // Map
       try{ctx.drawImage(img,0,headerH,W,mapH)}catch(e){console.warn('Overlap map draw failed',e)}
       URL.revokeObjectURL(svgUrl);

       // Footer CTA
       const fy=headerH+mapH;
