    const localCommunitiesDialog=document.getElementById('localCommunitiesDialog'),localCommunityConsentRow=document.getElementById('localCommunityConsentRow'),localCommunityStatus=document.getElementById('localCommunityStatus'),localCommunityResults=document.getElementById('localCommunityResults'),localCommunityPlace=document.getElementById('localCommunityPlace'),localFetlifeLinks=document.getElementById('localFetlifeLinks'),localRedditLinks=document.getElementById('localRedditLinks'),nationalCommunityList=document.getElementById('nationalCommunityList');
    let localCommunityAttempted=false,sessionLocation=null,sessionPlace=null;
    function localSearchLink(container,label,href){const link=document.createElement('a');link.href=href;link.target='_blank';link.rel='noopener noreferrer';link.textContent=label;container.append(link)}
    function topFetlifeCommunities(limit=5){
      const person=viewPerson();if(!person||!profiles[person])return [];
      const candidates=[];
      branches.forEach(branch=>branch.topics.forEach(label=>{
        const id='topic-'+slug(branch.name)+'-'+slug(label),pair=directPair(id,person),favorite=annotations[person]?.[id]==='favorite';
        const score=Math.max(pair.giveKnown?pair.give:-101,pair.receiveKnown?pair.receive:-101,favorite?101:-101),community=communityForLabel(label,'fetlife');
        if(score>0&&community&&community.url)candidates.push({label,score,community});
      }));
      visibleImportedDefinitions().forEach(item=>{const pair=directPair(item.id,person),favorite=annotations[person]?.[item.id]==='favorite',score=Math.max(pair.giveKnown?pair.give:-101,pair.receiveKnown?pair.receive:-101,favorite?101:-101),community=communityForLabel(item.label,'fetlife');if(score>0&&community&&community.url)candidates.push({label:item.label,score,community})});
      const seen=new Set();return candidates.sort((a,b)=>b.score-a.score||a.label.localeCompare(b.label)).filter(item=>{if(seen.has(item.community.url))return false;seen.add(item.community.url);return true}).slice(0,limit);
    }
    function renderNationalCommunities(){
      nationalCommunityList.replaceChildren();const groups=topFetlifeCommunities();
      if(!groups.length){const item=document.createElement('li'),note=document.createElement('small');note.textContent='Rate topics you’re into to see relevant national groups.';item.append(note);nationalCommunityList.append(item);return}
      groups.forEach(item=>{const row=document.createElement('li'),link=document.createElement('a'),note=document.createElement('small');link.href=item.community.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=item.community.name||item.label;note.textContent=`Matched from ${item.label}`;row.append(link,note);nationalCommunityList.append(row)});
    }
    function localSearchUrl(base,query,extra=''){return `${base}${encodeURIComponent(query)}${extra}`}
    function renderLocalCommunityResults(place){
      const city=(place&&place.city||'').trim(),state=(place&&place.state||'').trim(),area=[city,state].filter(Boolean).join(', '),query=city||state;
      localFetlifeLinks.replaceChildren();localRedditLinks.replaceChildren();
      if(!query){localCommunityPlace.textContent='Area name unavailable';localCommunityResults.hidden=true;return}
      localCommunityPlace.textContent=area;
      if(city)localSearchLink(localFetlifeLinks,`Groups in ${city}`,localSearchUrl('https://fetlife.com/groups/search?q=',city));
      if(state&&state!==city)localSearchLink(localFetlifeLinks,`Groups in ${state}`,localSearchUrl('https://fetlife.com/groups/search?q=',state));
      localSearchLink(localFetlifeLinks,'Search area places & events',localSearchUrl('https://fetlife.com/groups/search?q=',`${query} events`));
      localSearchLink(localRedditLinks,`Search Reddit for ${query} kink communities`,localSearchUrl('https://www.reddit.com/search/?q=',`${query} kink`,'&type=sr'));
      if(city){const subredditGuess=city.toLowerCase().replace(/[^a-z0-9]+/g,'');if(subredditGuess)localSearchLink(localRedditLinks,`Search for r/${subredditGuess}kink`,localSearchUrl('https://www.reddit.com/search/?q=',`r/${subredditGuess}kink`,'&type=sr'))}
      renderNationalCommunities();localCommunityResults.hidden=false;
    }
    async function reverseGeocodeSessionLocation(){
      const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),7000),lat=encodeURIComponent(sessionLocation.latitude),lon=encodeURIComponent(sessionLocation.longitude);
      try{
        const response=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lon}&zoom=10&addressdetails=1`,{headers:{Accept:'application/json'},credentials:'omit',cache:'no-store',referrerPolicy:'strict-origin-when-cross-origin',signal:controller.signal});
        if(!response.ok)throw new Error('Reverse geocoding unavailable');const data=await response.json(),address=data&&data.address||{};
        return {city:address.city||address.town||address.village||address.municipality||address.county||'',state:address.state||address.region||''};
      }finally{clearTimeout(timer)}
    }
