    function firstTopicSearchMatch(term){
      if(!term)return null;
      const branchMatch=branches.find(branch=>branch.name.toLowerCase().includes(term));
      const topicMatches=[];
      branches.forEach(branch=>branch.topics.forEach(topic=>{
        const label=topic.toLowerCase();
        if(label.includes(term))topicMatches.push({id:'topic-'+slug(branch.name)+'-'+slug(topic),branch:branch.name,label,starts:label.startsWith(term)});
      }));
      topicMatches.sort((a,b)=>Number(b.starts)-Number(a.starts)||a.label.localeCompare(b.label));
      if(topicMatches.length)return topicMatches[0];
      if(branchMatch)return {id:'cat-'+slug(branchMatch.name),branch:branchMatch.name,label:branchMatch.name.toLowerCase(),starts:branchMatch.name.toLowerCase().startsWith(term)};
      const imported=visibleImportedDefinitions().filter(item=>String(item.label||'').toLowerCase().includes(term)).sort((a,b)=>Number(String(b.label).toLowerCase().startsWith(term))-Number(String(a.label).toLowerCase().startsWith(term))||String(a.label).localeCompare(String(b.label)))[0];
      return imported?{id:imported.id,branch:imported.branch,parentId:imported.parentId}:null;
    }
