      if(!context){try{context=canvas.getContext('webgl')||canvas.getContext('experimental-webgl');if(context)level='WebGL 1'}catch(error){}}
      if(!context)return {pass:false,value:'Unavailable',detail:'WebGL is required for the sync map. Enable hardware acceleration or use a current browser and graphics driver.'};
